  if (!fetchImpl) throw new Error('fetch is not available');

  if (!config.mailchimpApiKey) throw new Error('mailchimpApiKey is required');
  if (!config.datadogApiKey) throw new Error('datadogApiKey is required');
  if (!config.datadogAppKey) throw new Error('datadogAppKey is required');
  if (!config.datadogSite) throw new Error('datadogSite is required');

