}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  mailchimpApiKey: string;
  datadogApiKey: string;
  datadogAppKey: string;
  datadogSite: string;
  fetch?: typeof fetch;
}

export interface MailchimpCallInput {
  mailchimpUrl?: string;
  mailchimpMethod?: string;
  mailchimpBody?: unknown;
  mailchimpHeaders?: Record<string, string>;
}

export interface HandleResult {
  datadogEventId: string;
  retryCount: number;
  finalStatus: number;
  success: boolean;
}

async function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function handle(payload: MailchimpCallInput, config: ConnectorConfig): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? globalThis.fetch;
  if (!fetchImpl) throw new Error('fetch is not available');

  if (!config.mailchimpApiKey) throw new Error('mailchimpApiKey is required');
  if (!config.datadogApiKey) throw new Error('datadogApiKey is required');
  if (!config.datadogAppKey) throw new Error('datadogAppKey is required');
  if (!config.datadogSite) throw new Error('datadogSite is required');

  let retryCount = 0;
  let finalStatus = 0;
  let finalErrorMessage = '';
  let success = false;

  if (!payload.mailchimpUrl) {
    const testEvent = await createDatadogEvent(fetchImpl, config, {
      title: 'Mailchimp API Rate Limit Test',
      text: 'Test event created without Mailchimp API call (no mailchimpUrl provided).',
      date: Math.floor(Date.now() / 1000),
      tags: ['mailchimp:rate_limit', 'test'],
      category: 'alert',
    });
    return {
      datadogEventId: testEvent.id,
      retryCount: 0,
      finalStatus: 0,
      success: false,
    };
  }

  const url = payload.mailchimpUrl;
  const method = payload.mailchimpMethod ?? 'GET';
  const body = payload.mailchimpBody ? JSON.stringify(payload.mailchimpBody) : undefined;
  const headers: Record<string, string> = {
    Authorization: `Bearer ${config.mailchimpApiKey}`,
    'Content-Type': 'application/json',
    ...payload.mailchimpHeaders,
  };

  const maxRetries = 3;
  const backoffBase = 1000;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const response = await fetchImpl(url, { method, headers, body });
    finalStatus = response.status;

    if (response.status === 429) {
      if (attempt < maxRetries) {
        retryCount++;
        const retryAfter = response.headers.get('Retry-After');
        let waitMs = backoffBase * Math.pow(2, attempt);
        if (retryAfter) {
          const retryAfterSec = parseInt(retryAfter, 10);
          if (!Number.isNaN(retryAfterSec)) waitMs = retryAfterSec * 1000;
        }
        await sleep(waitMs);
        continue;
      } else {
        const errorData = (await response.json().catch(() => ({}))) as Record<string, unknown>;
        finalErrorMessage = String(errorData.detail ?? errorData.title ?? 'Rate limit exceeded');
        break;
      }
    } else if (response.status >= 200 && response.status < 300) {
      success = true;
      break;
    } else {
      const errorData = (await response.json().catch(() => ({}))) as Record<string, unknown>;
      finalErrorMessage = String(errorData.detail ?? errorData.title ?? `HTTP ${response.status}`);
      break;
    }
  }

  const timestamp = Math.floor(Date.now() / 1000);
  const title = success ? 'Mailchimp API Call Succeeded After Retries' : 'Mailchimp API Rate Limit Exceeded';
  const text = success
    ? `Mailchimp API call succeeded after ${retryCount} retries. Final status: ${finalStatus}.`
    : `Mailchimp API call failed after ${retryCount} retries. Final status: ${finalStatus}, error: ${finalErrorMessage}`;

  const event = await createDatadogEvent(fetchImpl, config, {
    title,
    text,
    date: timestamp,
    tags: success ? ['mailchimp:rate_limit', 'retry_succeeded'] : ['mailchimp:rate_limit', 'retry_exhausted'],
    category: 'alert',
  });

  return {
    datadogEventId: event.id,
    retryCount,
    finalStatus,
    success,
  };
}

async function createDatadogEvent(
  fetchImpl: typeof fetch,
  config: ConnectorConfig,
  attributes: {
    title: string;
    text: string;
    date: number;
    tags: string[];
    category: 'alert' | 'change';
  }
): Promise<{ id: string }> {
  const url = `https://event-management-intake.${config.datadogSite}/api/v2/events`;
  const body = JSON.stringify({ data: { type: 'event', attributes } });

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'DD-API-KEY': config.datadogApiKey,
      'DD-APPLICATION-KEY': config.datadogAppKey,
      'Content-Type': 'application/json',
    },
    body,
  });

  if (response.status < 200 || response.status >= 300) {
    const errorText = await response.text().catch(() => '');
    throw new Error(`Datadog API error: ${response.status} ${response.statusText} - ${errorText}`);
  }

  const data = (await response.json()) as { data: { id: string } };
  return { id: data.data.id };
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { handle, ConnectorConfig, MailchimpCallInput } from './connector';
import { fakeFetch, jsonResponse, contractFetch, SOURCE_EXAMPLE, TARGET_ENDPOINTS } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-mailchimp-key',
