describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    mailchimpApiKey: 'mc-key',
    datadogApiKey: 'dd-api-key',
    datadogAppKey: 'dd-app-key',
    datadogSite: 'api.datadoghq.com',
  };

  it('retries on 429 with exponential backoff and succeeds on third attempt', async () => {
    let mailchimpCallCount = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('mailchimp')) {
        mailchimpCallCount++;
        if (mailchimpCallCount <= 2) {
          return jsonResponse(
            { type: 'TooManyRequests', title: 'Too Many Requests', status: 429, detail: 'Rate limit exceeded' },
            429,
          );
        } else {
          return jsonResponse({ success: true }, 200);
        }
      }
      if (req.url.includes('event-management-intake')) {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: MailchimpCallInput = {
      mailchimpUrl: 'https://us1.api.mailchimp.com/3.0/campaigns',
      mailchimpMethod: 'GET',
    };

    const result = await handle(payload, { ...baseConfig, fetch });

    expect(result.success).toBe(true);
    expect(result.retryCount).toBe(2);
    expect(result.finalStatus).toBe(200);
    expect(result.datadogEventId).toBe('1234567890abcdef');
    expect(mailchimpCallCount).toBe(3);
    expect(calls.length).toBe(4);
  });

  it('exhausts retries and logs failure to Datadog', async () => {
    let mailchimpCallCount = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('mailchimp')) {
        mailchimpCallCount++;
        return jsonResponse(
          {
            type: 'TooManyRequests',
            title: 'Too Many Requests',
            status: 429,
            detail: 'You have exceeded the limit of 10 simultaneous connections.',
          },
          429,
        );
      }
      if (req.url.includes('event-management-intake')) {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: MailchimpCallInput = {
      mailchimpUrl: 'https://us1.api.mailchimp.com/3.0/campaigns',
      mailchimpMethod: 'POST',
      mailchimpBody: { name: 'Test Campaign' },
    };

    const result = await handle(payload, { ...baseConfig, fetch });

    expect(result.success).toBe(false);
    expect(result.retryCount).toBe(3);
    expect(result.finalStatus).toBe(429);
    expect(result.datadogEventId).toBe('1234567890abcdef');
    expect(mailchimpCallCount).toBe(4);
    expect(calls.length).toBe(5);

    const datadogCall = calls.find((c) => c.url.includes('event-management-intake'));
    expect(datadogCall).toBeDefined();
    expect(datadogCall!.json).toMatchObject({
      data: {
        type: 'event',
        attributes: {
          title: 'Mailchimp API Rate Limit Exceeded',
          tags: ['mailchimp:rate_limit', 'retry_exhausted'],
          category: 'alert',
        },
      },
    });
    expect(String(datadogCall!.json.data.attributes.text)).toContain('failed after 3 retries');
    expect(String(datadogCall!.json.data.attributes.text)).toContain('You have exceeded the limit');
  });

  it('respects Retry-After header over exponential backoff', async () => {
    let mailchimpCallCount = 0;
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('mailchimp')) {
        mailchimpCallCount++;
        const response = jsonResponse(
          { type: 'TooManyRequests', title: 'Too Many Requests', status: 429, detail: 'Rate limit exceeded' },
          429,
        );
        response.headers.set('Retry-After', '5');
        if (mailchimpCallCount <= 2) return response;
        return jsonResponse({ success: true }, 200);
      }
      if (req.url.includes('event-management-intake')) {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: MailchimpCallInput = {
      mailchimpUrl: 'https://us1.api.mailchimp.com/3.0/campaigns',
    };

    vi.useFakeTimers();
    const promise = handle(payload, { ...baseConfig, fetch });
    await vi.advanceTimersByTimeAsync(5000);
    await vi.advanceTimersByTimeAsync(5000);
    const result = await promise;
    vi.useRealTimers();

    expect(result.success).toBe(true);
    expect(result.retryCount).toBe(2);
    expect(mailchimpCallCount).toBe(3);
  });

  it('does not retry on non-429 errors', async () => {
    let mailchimpCallCount = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('mailchimp')) {
        mailchimpCallCount++;
        return jsonResponse(
          { type: 'InvalidResource', title: 'Invalid Resource', status: 404, detail: 'Campaign not found' },
          404,
        );
      }
      if (req.url.includes('event-management-intake')) {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: MailchimpCallInput = {
      mailchimpUrl: 'https://us1.api.mailchimp.com/3.0/campaigns/123',
    };

    const result = await handle(payload, { ...baseConfig, fetch });

    expect(result.success).toBe(false);
    expect(result.retryCount).toBe(0);
    expect(result.finalStatus).toBe(404);
    expect(mailchimpCallCount).toBe(1);
    expect(calls.length).toBe(2);
  });

  it('throws on missing mailchimpApiKey', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: MailchimpCallInput = { mailchimpUrl: 'https://api.mailchimp.com/3.0/test' };
    await expect(handle(payload, { ...baseConfig, mailchimpApiKey: '', fetch })).rejects.toThrow(
      'mailchimpApiKey is required',
    );
  });

  it('throws on missing datadogApiKey', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: MailchimpCallInput = { mailchimpUrl: 'https://api.mailchimp.com/3.0/test' };
    await expect(handle(payload, { ...baseConfig, datadogApiKey: '', fetch })).rejects.toThrow(
      'datadogApiKey is required',
    );
  });

  it('throws on Datadog non-2xx response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('mailchimp')) {
        return jsonResponse({ success: true }, 200);
      }
      if (req.url.includes('event-management-intake')) {
        return jsonResponse({ error: 'Unauthorized' }, 401);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: MailchimpCallInput = { mailchimpUrl: 'https://api.mailchimp.com/3.0/test' };
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Datadog API error: 401 Unauthorized');
    expect(calls.length).toBe(2);
  });

  it('uses default GET method when not specified', async () => {
    let mailchimpCallCount = 0;
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('mailchimp')) {
        mailchimpCallCount++;
        expect(req.method).toBe('GET');
        return jsonResponse({ success: true }, 200);
      }
      if (req.url.includes('event-management-intake')) {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: MailchimpCallInput = { mailchimpUrl: 'https://api.mailchimp.com/3.0/test' };
    await handle(payload, { ...baseConfig, fetch });
    expect(mailchimpCallCount).toBe(1);
  });

  it('includes custom headers in Mailchimp request', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('mailchimp')) {
        expect(req.headers.get('X-Custom-Header')).toBe('custom-value');
        return jsonResponse({ success: true }, 200);
      }
      if (req.url.includes('event-management-intake')) {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: MailchimpCallInput = {
      mailchimpUrl: 'https://api.mailchimp.com/3.0/test',
      mailchimpHeaders: { 'X-Custom-Header': 'custom-value' },
    };
    await handle(payload, { ...baseConfig, fetch });
  });
});

